import SwiftUI

/*
 * "How this works" and "What's new" — the same two screens every AMS app
 * carries, written for the person using it. Kept in one place so a release
 * that changes behaviour changes the words beside it.
 */
struct GuideView: View {
    /// 2.22: the parts live in GuideContent.swift (pictures + short lines); every detail of the old long text is in docs/SPECIFICATION.md.
    static var sections: [GuideSection] { GuideContent.sections }
    /// Picture switch AMSWS_GUIDE=<part>: the page opens with that part's bigger view.
    var openFirst: String? = nil
    @State private var shown: GuideSection?
    @Environment(\.horizontalSizeClass) private var sizeClass
    /* iPhone: a sheet; iPad and Mac: the whole screen, since a sheet there is no bigger than the picture on the page. */
    private var asSheet: Binding<GuideSection?> { Binding(get: { sizeClass == .regular ? nil : shown }, set: { shown = $0 }) }
    private var asCover: Binding<GuideSection?> { Binding(get: { sizeClass == .regular ? shown : nil }, set: { shown = $0 }) }

    var body: some View {
        ScrollView {
            LazyVStack(alignment: .leading, spacing: 14) {
                Text("Every part of the app in one picture and a few lines. A number on a picture belongs to the line with the same number.")
                    .font(.subheadline).foregroundStyle(Theme.secondary)
                ForEach(Self.sections) { section in
                    GuidePartView(section: section) { shown = $0 }
                }
            }
            .padding(16).padding(.bottom, 32)
            .frame(maxWidth: 900)
            .frame(maxWidth: .infinity)
        }
        .background(Theme.bg.ignoresSafeArea())
        .navigationTitle("How this works")
        .navigationBarTitleDisplayMode(.inline)
        .accessibilityIdentifier("guide-page")
        .sheet(item: asSheet) { GuideViewerView(section: $0).presentationDetents([.large]) }
        .fullScreenCover(item: asCover) { GuideViewerView(section: $0) }
        .onAppear {
            if let name = openFirst, shown == nil { shown = Self.sections.first { $0.id == name } }
        }
    }
}

